// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract MockLendingPool is Ownable(msg.sender) {
    struct ReserveData {
        uint256 ltv; // Loan to value ratio (in basis points, e.g., 5000 = 50%)
        uint256 totalCollateral;
        uint256 totalBorrowed;
        mapping(address => uint256) userCollateral;
        mapping(address => uint256) userBorrowed;
    }

    mapping(address => ReserveData) public reserves;
    address public immutable wstETH;
    address public immutable eure;
    address public immutable usdc;

    event Deposit(address indexed user, address indexed asset, uint256 amount);
    event Borrow(address indexed user, address indexed asset, uint256 amount);

    constructor(address _wstETH, address _eure, address _usdc) {
        wstETH = _wstETH;
        eure = _eure;
        usdc = _usdc;

        // Initialize reserve data
        reserves[_wstETH].ltv = 5000; // 50% LTV
        reserves[_eure].ltv = 5000;
        reserves[_usdc].ltv = 5000;
    }

    function deposit(address asset, uint256 amount) external {
        require(asset == wstETH, "Only wstETH accepted as collateral");

        // Transfer tokens from user
        IERC20(asset).transferFrom(msg.sender, address(this), amount);

        // Update reserve data
        reserves[asset].totalCollateral += amount;
        reserves[asset].userCollateral[msg.sender] += amount;

        emit Deposit(msg.sender, asset, amount);
    }

    function borrow(uint256 amount, address stablecoin) external {
        require(amount > 0, "Amount must be greater than 0");
        require(stablecoin == eure || stablecoin == usdc, "Invalid stablecoin");

        // Calculate max borrowable amount based on collateral
        uint256 maxBorrowable = (reserves[wstETH].userCollateral[msg.sender] * reserves[wstETH].ltv) / 10000;
        require(amount <= maxBorrowable, "Borrow amount exceeds LTV limit");

        // Update reserve data
        reserves[stablecoin].totalBorrowed += amount;
        reserves[stablecoin].userBorrowed[msg.sender] += amount;

        // Transfer stablecoins to user
        IERC20(stablecoin).transfer(msg.sender, amount);

        emit Borrow(msg.sender, stablecoin, amount);
    }

    function getUserCollateral(address user) external view returns (uint256) {
        return reserves[wstETH].userCollateral[user];
    }

    function getUserBorrowed(address user) external view returns (uint256) {
        return reserves[eure].userBorrowed[user];
    }

    function getUserBorrowedUSDC(address user) external view returns (uint256) {
        return reserves[usdc].userBorrowed[user];
    }
}

